import * as React from "react";
import {
  Animated,
  Pressable,
  StyleSheet,
  Text,
  View,
  type StyleProp,
  type ViewStyle,
} from "react-native";
import { useOverlayTransition } from "@/components/native/overlay";
import { Portal } from "@/components/native/portal";
import { useTheme } from "@/components/native/theme";

export type TooltipProps = {
  content: string;
  children: React.ReactNode;
  /** Open on long press (default) or tap. */
  trigger?: "longPress" | "press";
  /** Auto-hide after this many ms. */
  duration?: number;
  style?: StyleProp<ViewStyle>;
};

type Rect = { x: number; y: number; width: number; height: number };

export function Tooltip({
  content,
  children,
  trigger = "longPress",
  duration = 1800,
  style,
}: TooltipProps) {
  const { colors } = useTheme();
  const anchor = React.useRef<View>(null);
  const host = React.useRef<View>(null);
  const [open, setOpen] = React.useState(false);
  const [rect, setRect] = React.useState<Rect | null>(null);
  const [hostRect, setHostRect] = React.useState<Rect | null>(null);
  const [tipWidth, setTipWidth] = React.useState(0);
  const { mounted, progress } = useOverlayTransition(open, { duration: 150 });

  React.useEffect(() => {
    if (!open) return;
    const t = setTimeout(() => setOpen(false), duration);
    return () => clearTimeout(t);
  }, [open, duration]);

  const show = () =>
    anchor.current?.measureInWindow((x, y, width, height) => {
      setRect({ x, y, width, height });
      setOpen(true);
    });

  const cx = rect && hostRect ? rect.x - hostRect.x + rect.width / 2 : 0;
  const top = rect && hostRect ? rect.y - hostRect.y - 44 : 0;
  const left = hostRect
    ? Math.max(8, Math.min(cx - tipWidth / 2, hostRect.width - tipWidth - 8))
    : 0;

  return (
    <>
      <Pressable
        ref={anchor}
        accessibilityHint={content}
        onLongPress={trigger === "longPress" ? show : undefined}
        onPress={trigger === "press" ? show : undefined}
        delayLongPress={350}
        style={style}
      >
        {children}
      </Pressable>
      {mounted && rect && (
        <Portal>
          <View
            ref={host}
            pointerEvents="none"
            style={StyleSheet.absoluteFill}
            onLayout={() =>
              host.current?.measureInWindow((x, y, w, h) =>
                setHostRect({ x, y, width: w, height: h }),
              )
            }
          >
            {hostRect && (
              <Animated.View
                onLayout={(e) => setTipWidth(e.nativeEvent.layout.width)}
                style={[
                  styles.tip,
                  {
                    top,
                    left,
                    backgroundColor: colors.primary,
                    opacity: progress,
                    transform: [
                      {
                        translateY: progress.interpolate({
                          inputRange: [0, 1],
                          outputRange: [4, 0],
                        }),
                      },
                      {
                        scale: progress.interpolate({ inputRange: [0, 1], outputRange: [0.9, 1] }),
                      },
                    ],
                  },
                ]}
              >
                <Text style={[styles.text, { color: colors.primaryForeground }]}>{content}</Text>
                <View
                  style={[
                    styles.arrow,
                    {
                      left: Math.max(10, Math.min(cx - left - 5, tipWidth - 20)),
                      backgroundColor: colors.primary,
                    },
                  ]}
                />
              </Animated.View>
            )}
          </View>
        </Portal>
      )}
    </>
  );
}

const styles = StyleSheet.create({
  tip: {
    position: "absolute",
    height: 34,
    paddingHorizontal: 12,
    borderRadius: 10,
    justifyContent: "center",
    maxWidth: 260,
  },
  text: { fontSize: 13, fontWeight: "500" },
  arrow: {
    position: "absolute",
    bottom: -4,
    width: 10,
    height: 10,
    borderRadius: 2,
    transform: [{ rotate: "45deg" }],
  },
});

/**
 * Shared overlay plumbing for Dialog, Sheet, Select, Drawer…
 * - useOverlayTransition: keeps the tree mounted while the exit animation runs.
 * - useBackHandler: Android back button (Escape key on web).
 * - Backdrop: an animated, pressable scrim.
 */
import * as React from "react";
import { Animated, BackHandler, Easing, Platform, Pressable, StyleSheet } from "react-native";
import { nativeDriver, useTheme } from "@/components/native/theme";

export function useOverlayTransition(
  open: boolean,
  { enter = "spring", duration = 220 }: { enter?: "spring" | "timing"; duration?: number } = {},
) {
  const progress = React.useRef(new Animated.Value(0)).current;
  const [mounted, setMounted] = React.useState(open);
  const target = React.useRef(open ? 1 : 0);
  const alive = React.useRef(true);

  React.useEffect(() => {
    alive.current = true;
    return () => {
      alive.current = false;
    };
  }, []);

  const run = React.useCallback(
    (to: 0 | 1) => {
      target.current = to;
      const anim =
        to === 1
          ? enter === "spring"
            ? Animated.spring(progress, {
                toValue: 1,
                useNativeDriver: nativeDriver,
                damping: 22,
                stiffness: 260,
                mass: 0.9,
              })
            : Animated.timing(progress, {
                toValue: 1,
                duration,
                easing: Easing.out(Easing.cubic),
                useNativeDriver: nativeDriver,
              })
          : Animated.timing(progress, {
              toValue: 0,
              duration: Math.round(duration * 0.8),
              easing: Easing.in(Easing.cubic),
              useNativeDriver: nativeDriver,
            });

      anim.start(({ finished }) => {
        if (!alive.current || target.current !== to) return; // superseded or unmounted
        if (!finished) {
          // Interrupted, e.g. the animated views re-attached (StrictMode, portal
          // remount). Resume from the current value on the next frame.
          requestAnimationFrame(() => alive.current && target.current === to && run(to));
          return;
        }
        if (to === 0) setMounted(false);
      });
    },
    [enter, duration, progress],
  );

  React.useEffect(() => {
    if (open) {
      setMounted(true);
      run(1);
    } else if (target.current === 1) {
      run(0);
    }
  }, [open, run]);

  return { mounted, progress };
}

/** Closes on the Android hardware back button, or Escape on the web, while `active`. */
export function useBackHandler(active: boolean, onBack: () => void) {
  React.useEffect(() => {
    if (!active) return;
    if (Platform.OS === "web") {
      const onKey = (e: KeyboardEvent) => e.key === "Escape" && onBack();
      window.addEventListener("keydown", onKey);
      return () => window.removeEventListener("keydown", onKey);
    }
    const sub = BackHandler.addEventListener("hardwareBackPress", () => {
      onBack();
      return true;
    });
    return () => sub.remove();
  }, [active, onBack]);
}

export function Backdrop({
  progress,
  onPress,
  dismissible = true,
}: {
  progress: Animated.Value;
  onPress?: () => void;
  dismissible?: boolean;
}) {
  const { colors } = useTheme();
  return (
    <Animated.View
      style={[StyleSheet.absoluteFill, { backgroundColor: colors.overlay, opacity: progress }]}
    >
      <Pressable
        accessibilityRole="button"
        accessibilityLabel="Close"
        style={StyleSheet.absoluteFill}
        onPress={dismissible ? onPress : undefined}
      />
    </Animated.View>
  );
}

/**
 * Portal + PortalHost.
 *
 * Overlays (Dialog, Sheet, Select, Toast…) render into the nearest <PortalHost>
 * so they sit above your navigation. Put one at the root of your app:
 *
 *   <PortalHost>
 *     <Stack />
 *   </PortalHost>
 *
 * Without a host, overlays fall back to a transparent React Native <Modal>.
 */
import * as React from "react";
import { Modal, StyleSheet, View } from "react-native";

type Store = {
  set: (key: string, node: React.ReactNode) => void;
  remove: (key: string) => void;
};

const PortalContext = React.createContext<Store | null>(null);

export function PortalHost({ children }: { children?: React.ReactNode }) {
  const [nodes, setNodes] = React.useState<[string, React.ReactNode][]>([]);

  const store = React.useMemo<Store>(
    () => ({
      set: (key, node) =>
        setNodes((prev) => {
          const i = prev.findIndex(([k]) => k === key);
          if (i === -1) return [...prev, [key, node]];
          const next = prev.slice();
          next[i] = [key, node];
          return next;
        }),
      remove: (key) => setNodes((prev) => prev.filter(([k]) => k !== key)),
    }),
    [],
  );

  return (
    <PortalContext.Provider value={store}>
      <View style={styles.root}>
        {children}
        <View pointerEvents="box-none" style={StyleSheet.absoluteFill}>
          {nodes.map(([key, node]) => (
            <React.Fragment key={key}>{node}</React.Fragment>
          ))}
        </View>
      </View>
    </PortalContext.Provider>
  );
}

export function Portal({ children }: { children: React.ReactNode }) {
  const store = React.useContext(PortalContext);
  const key = React.useId();

  React.useLayoutEffect(() => {
    store?.set(key, children);
  }, [store, key, children]);

  React.useLayoutEffect(() => {
    return () => store?.remove(key);
  }, [store, key]);

  if (store) return null;
  return (
    <Modal transparent visible animationType="none" statusBarTranslucent>
      {children}
    </Modal>
  );
}

const styles = StyleSheet.create({
  root: { flex: 1 },
});

/**
 * Synapse UI Native: design tokens and theme.
 *
 * Every native component reads its colors from `useTheme()`. Wrap your app in
 * <ThemeProvider> to force a scheme or override colors; without it the system
 * color scheme is used.
 */
import * as React from "react";
import { Platform, useColorScheme, type ViewStyle } from "react-native";

export const palette = {
  light: {
    background: "#ffffff",
    foreground: "#0a0a0b",
    card: "#ffffff",
    cardForeground: "#0a0a0b",
    surface: "#fafafa",
    surfaceStrong: "#f4f4f5",
    muted: "#f4f4f5",
    mutedForeground: "#71717a",
    subtle: "#a1a1aa",
    border: "#e7e7ea",
    borderStrong: "#d4d4d8",
    input: "#e4e4e7",
    ring: "#a1a1aa",
    primary: "#18181b",
    primaryForeground: "#fafafa",
    secondary: "#f4f4f5",
    secondaryForeground: "#18181b",
    accent: "#f4f4f5",
    accentForeground: "#18181b",
    brand: "#2563eb",
    brandForeground: "#ffffff",
    brandSoft: "#eff4ff",
    success: "#16a34a",
    successSoft: "#ecfdf3",
    warning: "#d97706",
    warningSoft: "#fffaeb",
    destructive: "#dc2626",
    destructiveForeground: "#ffffff",
    destructiveSoft: "#fef2f2",
    overlay: "rgba(9, 9, 11, 0.42)",
    shadow: "#0a0a0b",
  },
  dark: {
    background: "#09090b",
    foreground: "#f4f4f5",
    card: "#111113",
    cardForeground: "#f4f4f5",
    surface: "#111113",
    surfaceStrong: "#18181b",
    muted: "#18181b",
    mutedForeground: "#a1a1aa",
    subtle: "#71717a",
    border: "#232327",
    borderStrong: "#2e2e33",
    input: "#27272a",
    ring: "#52525b",
    primary: "#f4f4f5",
    primaryForeground: "#09090b",
    secondary: "#1c1c1f",
    secondaryForeground: "#f4f4f5",
    accent: "#1f1f23",
    accentForeground: "#f4f4f5",
    brand: "#3b82f6",
    brandForeground: "#ffffff",
    brandSoft: "#172036",
    success: "#4ade80",
    successSoft: "#0f2418",
    warning: "#fbbf24",
    warningSoft: "#2a2110",
    destructive: "#f87171",
    destructiveForeground: "#0a0a0b",
    destructiveSoft: "#2a1414",
    overlay: "rgba(0, 0, 0, 0.62)",
    shadow: "#000000",
  },
};

export type ThemeColors = typeof palette.light;
export type ColorScheme = "light" | "dark";

export const radius = { xs: 6, sm: 8, md: 12, lg: 16, xl: 20, "2xl": 24, "3xl": 32, full: 9999 };

/** 4pt spacing scale: space(4) === 16. */
export const space = (n: number) => n * 4;

export const fontSize = {
  xs: 12,
  sm: 14,
  base: 16,
  lg: 18,
  xl: 20,
  "2xl": 24,
  "3xl": 30,
  "4xl": 36,
};

export const fontWeight = {
  regular: "400",
  medium: "500",
  semibold: "600",
  bold: "700",
} as const;

export const fontFamily = {
  mono: Platform.select({
    ios: "Menlo",
    android: "monospace",
    default: "ui-monospace, Menlo, monospace",
  }),
};

/** Animated: use the native driver everywhere except react-native-web. */
export const nativeDriver = Platform.OS !== "web";

/** Cross-platform elevation. Level 0–4. */
export function shadow(level: 0 | 1 | 2 | 3 | 4, scheme: ColorScheme = "light"): ViewStyle {
  if (level === 0) return {};
  const dark = scheme === "dark";
  const y = [0, 1, 4, 10, 18][level];
  const blur = [0, 3, 12, 28, 44][level];
  const alpha = (dark ? [0, 0.4, 0.5, 0.55, 0.6] : [0, 0.06, 0.08, 0.12, 0.16])[level];
  if (Platform.OS === "web") {
    return { boxShadow: `0px ${y}px ${blur}px rgba(0,0,0,${alpha})` } as ViewStyle;
  }
  return {
    shadowColor: "#000",
    shadowOffset: { width: 0, height: y },
    shadowOpacity: alpha,
    shadowRadius: blur / 2,
    elevation: level * 3,
  };
}

/** Hex color to rgba(). */
export function alpha(hex: string, a: number) {
  const h = hex.replace("#", "");
  const n = parseInt(h.length === 3 ? h.replace(/./g, (c) => c + c) : h, 16);
  return `rgba(${(n >> 16) & 255}, ${(n >> 8) & 255}, ${n & 255}, ${a})`;
}

type ThemeValue = {
  scheme: ColorScheme;
  colors: ThemeColors;
  radius: typeof radius;
  space: typeof space;
  fontSize: typeof fontSize;
  fontWeight: typeof fontWeight;
  shadow: (level: 0 | 1 | 2 | 3 | 4) => ViewStyle;
};

const ThemeContext = React.createContext<{
  scheme?: ColorScheme;
  colors?: Partial<Record<ColorScheme, Partial<ThemeColors>>>;
} | null>(null);

export function ThemeProvider({
  scheme,
  colors,
  children,
}: {
  /** Force a scheme. Defaults to the device setting. */
  scheme?: ColorScheme;
  /** Override tokens per scheme, e.g. `{ light: { brand: "#7c3aed" } }`. */
  colors?: Partial<Record<ColorScheme, Partial<ThemeColors>>>;
  children: React.ReactNode;
}) {
  const value = React.useMemo(() => ({ scheme, colors }), [scheme, colors]);
  return <ThemeContext.Provider value={value}>{children}</ThemeContext.Provider>;
}

export function useTheme(): ThemeValue {
  const ctx = React.useContext(ThemeContext);
  const system = useColorScheme();
  const scheme: ColorScheme = ctx?.scheme ?? (system === "dark" ? "dark" : "light");
  return React.useMemo(
    () => ({
      scheme,
      colors: { ...palette[scheme], ...(ctx?.colors?.[scheme] ?? {}) },
      radius,
      space,
      fontSize,
      fontWeight,
      shadow: (level: 0 | 1 | 2 | 3 | 4) => shadow(level, scheme),
    }),
    [scheme, ctx?.colors],
  );
}
